## Why This Is Asked
This question probes real-time blind source separation under changing source counts and practical latency constraints in a busy open-plan office—a common production scenario.

## Key Concepts
- Online whitening with forgetting factors to handle nonstationary noise
- MDL-based dynamic model-order estimation for adaptive source-count tracking
- Per-bin ICA with natural gradient updates and adaptive demixer sizing (6×K per frequency bin)
- Cross-bin permutation resolution via envelope coherence
- On-device evaluation using SDR/SIR metrics with ground-truth sources

## Code Example
```javascript
class AdaptiveConvolutiveICA {
  constructor(nMics, frameSize, hopSize, maxSources = 5) {
    this.nMics = nMics;
    this.frameSize = frameSize;
    this.hopSize = hopSize;
    this.maxSources = maxSources;
    this.binCount = frameSize / 2 + 1;
    this.demixers = [];  // Per-bin demixing matrices
    this.sourceCount = 1;
    this.forgettingFactor = 0.999;
    this.whiteningMatrix = this.computeInitialWhitening();
  }

  estimateSourceCount(covarianceMatrix) {
    const eigenvalues = this.computeEigenvalues(covarianceMatrix);
    const mdlScores = eigenvalues.map((_, k) =>
      this.computeMDLScore(eigenvalues, k + 1)
    );
    return mdlScores.indexOf(Math.min(...mdlScores)) + 1;
  }

  computeMDLScore(eigenvalues, k) {
    const n = eigenvalues.length;
    const lambda = eigenvalues.slice(0, k);
    const rho = eigenvalues.slice(k);
    const L = -k * n / 2 * Math.log(lambda.reduce((a, b) => a * b, 1) ** (1/n));
    const P = -rho.length * n / 2 * Math.log(rho.reduce((a, b) => a * b, 1) ** (1/n));
    const penalty = k / 2 * Math.log(n) * n;
    return -L - P + penalty;
  }

  updateDemixer(binIdx, gradient) {
    const W = this.demixers[binIdx];
    const mu = 0.01 / (1 + 0.001 * this.iteration);
    const I = Matrix.eye(W.rows);
    const gradOrtho = W - W.T.inv().T;  // Natural gradient approximation
    this.demixers[binIdx] = W + mu * gradOrtho;
  }

  resolvePermutation() {
    const envelopes = this.demixers.map(W =>
      this.computeEnvelope(W * this.mixings[W.rows])
    );
    const correlations = this.computeCorrelationMatrix(envelopes);
    return this.hungarianAssignment(correlations);
  }

  computeEnvelope(signal) {
    return signal.map(x => Math.abs(x) + 0.001);
  }

  processFrame(mixture) {
    const spectrum = this.stft(mixture);
    const whitened = spectrum.map(bin => this.whiteningMatrix.dot(bin));

    // Update source count estimate every N frames
    if (this.frameCount % 100 === 0) {
      const cov = this.estimateCovariance(whitened);
      this.sourceCount = Math.min(
        this.estimateSourceCount(cov),
        this.maxSources
      );
      this.resizeDemixers();
    }

    this.demixers = whitened.map((bin, i) => {
      const gradient = this.computeGradient(bin, this.demixers[i]);
      return this.updateDemixer(i, gradient);
    });

    const separation = this.demixers.map(W => W.dot(spectrum));
    const perm = this.resolvePermutation();
    return this.permuteAndISTFT(separation, perm);
  }

  resizeDemixers() {
    this.demixers = this.demixers.map(W => {
      if (W.cols < this.sourceCount) {
        return Matrix.concat(W, Matrix.rand(W.rows, this.sourceCount - W.cols));
      }
      return W.slice(0, W.rows, 0, this.sourceCount);
    });
  }
}

// On-device evaluation with ground-truth sources
function evaluateSeparation(estimated, groundTruth) {
  const SDR = computeSDR(estimated, groundTruth);
  const SIR = computeSIR(estimated, groundTruth);
  const SAR = computeSAR(estimated, groundTruth);
  return { SDR, SIR, SAR };
}
```

